var line = msg.payload.trim();
if (line.startsWith('[')) {
    msg.payload = line;
    return msg;
}
return null;

var topic = msg.payload[0];
var data = msg.payload[1];

msg.event = {
    type: data.type,
    createdAt: new Date()
};
msg.payload = {
    type: data.type
};

node.status({fill: data.type === 'urgent' ? 'red' : 'blue', shape: 'dot', text: data.type + ' @ ' + new Date().toLocaleTimeString()});

return msg;

var deviceId = '6a119679c7a8be5c1d97955d';
var deviceSecret = '98db90bfe796872d758dce1c2d6a25623c4ebe6116ef632ed5912b8fcf8069d7';
var timestamp = Math.floor(Date.now() / 1000).toString();
var url = '/api/notifications/create';
var body = JSON.stringify(msg.payload);

var signPayload = 'POST|' + url + '|' + timestamp + '|' + body;
var signature = crypto.createHmac('sha256', deviceSecret).update(signPayload).digest('hex');

msg.headers = {
    'Content-Type': 'application/json',
    'X-Device-Id': deviceId,
    'X-Timestamp': timestamp,
    'X-Signature': signature
};

return msg;

if (typeof msg.statusCode !== 'number') {
    return [null, null, null];
}

var eventType = (msg.event && msg.event.type) || 'unknown';
var eventCreatedAt = (msg.event && msg.event.createdAt) || new Date();

if (msg.statusCode === 201) {
    var dbMsg = {payload: {
        type: eventType,
        status: 'synced',
        createdAt: eventCreatedAt,
        syncedAt: new Date()
    }};
    var ledMsg = {payload: '["led/-/set",{"state":"success"}]'};
    node.status({fill: 'green', shape: 'dot', text: 'success (' + msg.statusCode + ')'});
    return [dbMsg, ledMsg, null];
}

var dbMsg = {payload: {
    type: eventType,
    status: 'pending',
    createdAt: eventCreatedAt,
    syncedAt: null
}};
var ledMsg = {payload: '["led/-/set",{"state":"error"}]'};
node.status({fill: 'red', shape: 'dot', text: 'HTTP ' + msg.statusCode});
return [dbMsg, ledMsg, {payload: msg.statusCode}];

var eventType = (msg.event && msg.event.type) || 'unknown';
var eventCreatedAt = (msg.event && msg.event.createdAt) || new Date();

var dbMsg = {payload: {
    type: eventType,
    status: 'pending',
    createdAt: eventCreatedAt,
    syncedAt: null
}};

var ledMsg = {payload: '["led/-/set",{"state":"error"}]'};

var errMsg = (msg.error && msg.error.message) || 'unknown';
node.status({fill: 'red', shape: 'dot', text: 'error: ' + errMsg});

return [dbMsg, ledMsg];

var events = msg.payload;
if (!events || events.length === 0) {
    return null;
}

var pending = events.filter(function(e) {
    return e.status === 'pending';
});

if (pending.length === 0) return null;

node.status({text: pending.length + ' pending'});

var messages = pending.map(function(e) {
    return {
        payload: { type: e.type },
        eventDbId: e._id.toString()
    };
});

return [messages];

var deviceId = '6a119679c7a8be5c1d97955d';
var deviceSecret = '98db90bfe796872d758dce1c2d6a25623c4ebe6116ef632ed5912b8fcf8069d7';
var timestamp = Math.floor(Date.now() / 1000).toString();
var url = '/api/notifications/create';
var body = JSON.stringify(msg.payload);

var signPayload = 'POST|' + url + '|' + timestamp + '|' + body;
var signature = crypto.createHmac('sha256', deviceSecret).update(signPayload).digest('hex');

msg.headers = {
    'Content-Type': 'application/json',
    'X-Device-Id': deviceId,
    'X-Timestamp': timestamp,
    'X-Signature': signature
};

return msg;

if (msg.statusCode !== 201 || !msg.eventDbId) {
    node.status({fill: 'red', shape: 'dot', text: 'still pending'});
    return null;
}

msg.query = { _id: msg.eventDbId };
msg.payload = { $set: { status: 'synced', syncedAt: new Date() } };
node.status({fill: 'green', shape: 'dot', text: 'synced'});
return msg;

var cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);
msg.payload = {
    status: 'synced',
    syncedAt: { $lt: cutoff }
};
return msg;
